<template>
  <view class="dz-page order-detail-page">
    <header class="page-head"><button aria-label="返回" @tap="goBack">‹</button><text>订单详情</text><view role="button" @tap="showPending('客服')">♧ 客服</view></header>
    <view v-if="loading" class="booking-empty">正在加载订单…</view>
    <view v-else-if="order" class="detail-content">
      <section class="status-hero"><view class="clock">◷</view><view><strong>{{ statusCopy.title }}</strong><text>{{ statusCopy.description }}</text></view><view class="progress"><view v-for="(step,index) in steps" :key="step" :class="{done:index<statusCopy.step,active:index===statusCopy.step}"><i>{{ index<statusCopy.step?'✓':'' }}</i><text>{{ step }}</text></view></view></section>
      <section class="provider-card panel"><view class="avatar"><image v-if="order.provider_avatar_url" :src="order.provider_avatar_url" mode="aspectFill"/><text v-else>{{ order.provider_name.slice(0,1) }}</text></view><view class="provider-copy"><view><strong>{{ order.provider_name }}</strong><text>{{ order.service_name }}</text></view><text>★ 4.9分</text></view><view class="contact-actions"><button @tap="showPending('私信')">◌ 私信</button><button @tap="showPending('电话联系')">⌕ 电话联系</button></view></section>
      <section class="info-card panel"><view><i>◷</i><text>服务时间</text><strong>{{ timeLabel }}</strong></view><view><i>●</i><text>集合地点</text><strong>{{ order.meeting_address }}</strong><button @tap="showPending('导航')">导航</button></view><view class="map"><view class="roads"/><i>●</i></view><view><i>▤</i><text>订单编号</text><strong class="muted">{{ order.order_no }}</strong><button @tap="copyOrderNo">▣</button></view><view><i>▦</i><text>创建时间</text><strong class="muted">{{ createdLabel }}</strong></view></section>
      <section class="fees panel"><view><text>服务费</text><text>¥{{ money(order.service_fee_amount) }}</text></view><view><text>交通费</text><text>¥{{ money(order.transport_fee_amount) }}</text></view><view><text>优惠券</text><text class="discount">−¥{{ money(order.discount_amount) }}</text></view><view class="total"><text>{{ order.paid_at?'实付':'应付' }}</text><strong>¥{{ money(order.payable_amount) }}</strong></view></section>
      <section class="safety panel"><button @tap="showPending('集合照片')"><i>▣</i><view><strong>集合照片待上传</strong><text>到达集合地点后，请上传集合照片</text></view><b>›</b></button><button @tap="showPending('持续定位')"><i>●</i><view><strong>服务中持续定位</strong><text>为保障安全，服务中将持续共享位置</text></view><b>›</b></button><button @tap="showPending('紧急客服')"><i>☎</i><view><strong>紧急联系客服</strong><text>如遇紧急情况，请及时联系客服</text></view><b>›</b></button></section>
    </view>
    <view v-else class="booking-empty">{{ error || '订单不存在' }}</view>
    <footer v-if="order&&showActions" class="detail-footer"><button v-if="order.status==='pending_payment'" class="outline" @tap="cancel">取消订单</button><button v-if="order.status==='pending_payment'" class="primary" @tap="continuePay">继续支付</button><button v-else class="outline" @tap="showPending('联系客服')">联系客服</button><button v-if="['pending_acceptance','pending_service','departed','in_service'].includes(order.status)" class="primary" @tap="showPending('联系达人')">联系达人</button></footer>
  </view>
</template>

<script setup lang="ts">
import { computed, ref } from 'vue'; import { onLoad, onShow } from '@dcloudio/uni-app'; import { cancelProviderOrder, getProviderOrder } from '@/services/orders'; import { orderStatusCopy } from '@/services/orderPresentation'; import { isAuthenticated } from '@/services/session'; import type { ProviderOrder } from '@/types/api'; import { formatAmount, getErrorMessage } from '@/utils/formatters'
const orderNo=ref(''),order=ref<ProviderOrder|null>(null),loading=ref(true),error=ref('');const steps=['已支付','已接单','待出发','服务中','待确认'];const statusCopy=computed(()=>orderStatusCopy(order.value?.status||'')),showActions=computed(()=>order.value&&!['completed','cancelled','refunded'].includes(order.value.status)),money=formatAmount
const timeLabel=computed(()=>{if(!order.value)return'';const s=new Date(order.value.starts_at),e=new Date(order.value.ends_at);return `${String(s.getMonth()+1).padStart(2,'0')}月${String(s.getDate()).padStart(2,'0')}日 ${String(s.getHours()).padStart(2,'0')}:${String(s.getMinutes()).padStart(2,'0')}—${String(e.getHours()).padStart(2,'0')}:${String(e.getMinutes()).padStart(2,'0')}`});const createdLabel=computed(()=>order.value?new Date(order.value.created_at).toLocaleString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}):'')
function goBack(){uni.navigateBack()}function showPending(name:string){uni.showToast({title:`${name}功能即将接入`,icon:'none'})}function copyOrderNo(){if(order.value)uni.setClipboardData({data:order.value.order_no})}function continuePay(){if(order.value)uni.navigateTo({url:`/pages/booking/payment?orderNo=${order.value.order_no}`})}
function cancel(){if(!order.value)return;uni.showModal({title:'取消订单',content:'取消后将立即释放达人档期。',success:async result=>{if(!result.confirm)return;try{order.value=(await cancelProviderOrder(order.value!.order_no)).data}catch(reason){uni.showToast({title:getErrorMessage(reason,'取消失败'),icon:'none'})}}})}
async function load(){if(!orderNo.value)return;loading.value=true;error.value='';try{order.value=(await getProviderOrder(orderNo.value)).data}catch(reason){error.value=getErrorMessage(reason)}finally{loading.value=false}}
onLoad(query=>{orderNo.value=typeof query?.orderNo==='string'?query.orderNo:''});onShow(()=>{if(isAuthenticated())load()})
</script>

